def rd_amp_ansatz0(ff, frd, fda, a0, lambda_, sigma, lc):
    """``IMRPhenomXHM_RD_Amp_Ansatz`` (version 0): the ringdown amplitude
    rescaled by the leading order of the 22, ``fda |a0| sigma exp(-dfr
    lambda / dfd) / (dfr^2 + dfd^2) f^(-lc)``."""
